package q.qedet.organization.service;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import q.qedet.auth.security.ActorContext; import q.qedet.common.exception.*; import q.qedet.organization.dto.OrganizationBinRequest; import q.qedet.organization.entity.*; import q.qedet.organization.repository.*; import java.util.*; import static q.qedet.common.model.Permission.LOCATION_MANAGE;
@Service public class OrganizationBinService {
 private final OrganizationZoneRepository zones;private final OrganizationBinRepository bins;private final ActorContext actor;
 public OrganizationBinService(OrganizationZoneRepository zones,OrganizationBinRepository bins,ActorContext actor){this.zones=zones;this.bins=bins;this.actor=actor;}
 @Transactional public OrganizationBin create(UUID organizationId,UUID zoneId,OrganizationBinRequest request){tenant(organizationId);actor.requirePermission(LOCATION_MANAGE);OrganizationZone zone=zones.findByIdAndSiteOrganizationId(zoneId,organizationId).orElseThrow(()->new NotFoundException("Zone not found"));String code=req(request.code());if(bins.findByZoneIdAndCodeIgnoreCase(zoneId,code).isPresent())throw new ConflictException("Bin code already exists in this zone");OrganizationBin bin=new OrganizationBin(zone,code,req(request.name()));apply(bin,request);return bins.save(bin);}
 private void apply(OrganizationBin b,OrganizationBinRequest r){b.setDescription(blank(r.description()));if(r.active()!=null)b.setActive(r.active());if(r.capacity()!=null&&r.capacity().signum()<0)throw new BadRequestException("Capacity cannot be negative");b.setCapacity(r.capacity());}private void tenant(UUID org){if(!org.equals(actor.organizationId()))throw new ForbiddenException("Organization access denied");}private String req(String s){if(s==null||s.isBlank())throw new BadRequestException("Code and name are required");return s.trim();}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
